+			await db.setObjectBulk(restricted.map((uid, index) => [
+				`user:${uid}:settings`, {
+					chatAllowList: JSON.stringify(following[index].map(String)),
+					// An empty allow list is open, so preserve the old closed setting.
+					...(following[index].length ? {} : { disableIncomingMessages: 1 }),
+				},
+			]));
+			progress.incr(uids.length);
+		}, { batch: 500 });
+	},
+};
